INSERT INTO feature VALUES('re-verification','workflow','Re-verification obligations on a pull request','executable-specifications','implemented','notable',NULL,'A change owes re-verification by every specification naming a changed item: the pull request body carries the obligations as boxes the lane fails while unticked; a performance fix owes a lint assessment whose verdict is `could: yes — <lint>, <reference>` or `could: no — <one sentence>`.',NULL,'.config/obligations',NULL,NULL);
